{"engine": "jinja2", "source": "{% extends "base.html" %}
{% block content %}
  <article>
    <h1>{{ page.title }}</h1>
    <p class="meta">{{ page.published_at|date("Y-m-d") }} by {{ page.author.name }}</p>
    {{ page.body|safe }}
    {% for tag in page.tags %}<span class="tag">{{ tag }}</span>{% endfor %}
  </article>
{% endblock %}
"}

{"source": "{% for product in collection.products %}
  <div class="card">
    <a href="{{ product.url | within: collection }}">
      <img src="{{ product.featured_image | img_url: '400x' }}" alt="{{ product.title | escape }}">
      <h3>{{ product.title }}</h3>
      <span>{{ product.price | money }}</span>
    </a>
  </div>
{% else %}
  <p>No products yet.</p>
{% endfor %}
"}

